INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'An object that is thrown, kicked, or launched and is acted upon mainly by gravity after release.', NULL, NULL, NULL, NULL, 'Projectile', 'The correct term is: Projectile.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The curved path followed by a projectile during its motion.', NULL, NULL, NULL, NULL, 'Trajectory', 'The correct term is: Trajectory.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The two independent motions that combine to produce projectile motion.', NULL, NULL, NULL, NULL, 'Constant horizontal motion and accelerated vertical free fall', 'The correct term is: Constant horizontal motion and accelerated vertical free fall.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The launch angle that produces the maximum horizontal range on level ground.', NULL, NULL, NULL, NULL, '45°', 'The correct term is: 45°.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The launch angle that produces the greatest maximum height.', NULL, NULL, NULL, NULL, '90° (straight upward)', 'The correct term is: 90° (straight upward).', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'If a ball is thrown horizontally while another is dropped from the same height at the same time, what happens to both balls?', NULL, NULL, NULL, NULL, 'Both hit the ground at the same time', 'The correct term is: Both hit the ground at the same time.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The horizontal distance traveled by a projectile from launch to landing.', NULL, NULL, NULL, NULL, 'Range', 'The correct term is: Range.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'The greatest vertical distance a projectile reaches above its launch point.', NULL, NULL, NULL, NULL, 'Maximum height', 'The correct term is: Maximum height.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'If the launch angle remains constant, what happens to the range and maximum height as launch speed increases?', NULL, NULL, NULL, NULL, 'Both range and height increase', 'The correct term is: Both range and height increase.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Ignoring air resistance, what is the only force acting on a projectile after it is released?', NULL, NULL, NULL, NULL, 'Gravity', 'The correct term is: Gravity.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Two launch angles that add up to 90° and produce the same range are called what?', NULL, NULL, NULL, NULL, 'Complementary angles', 'The correct term is: Complementary angles.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Between launch angles of 30° and 60° with the same launch speed, which angle produces the greater maximum height?', NULL, NULL, NULL, NULL, '60°', 'The correct term is: 60°.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Why do basketball players often use a high arc when shooting?', NULL, NULL, NULL, NULL, 'More flight time and a better entry angle to the hoop', 'The correct term is: More flight time and a better entry angle to the hoop.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Between launch angles of 20° and 70° with the same launch speed, which angle has the shorter flight time?', NULL, NULL, NULL, NULL, '20°', 'The correct term is: 20°.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'How does the horizontal velocity of a projectile behave during flight when air resistance is ignored?', NULL, NULL, NULL, NULL, 'Remains constant', 'The correct term is: Remains constant.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'What is the vertical velocity of a projectile at the highest point of its trajectory?', NULL, NULL, NULL, NULL, 'Zero', 'The correct term is: Zero.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Compared with the ideal prediction, what effect does air resistance have on a projectile''s range?', NULL, NULL, NULL, NULL, 'Makes the range shorter', 'The correct term is: Makes the range shorter.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'What launch condition helps a long jumper achieve maximum range?', NULL, NULL, NULL, NULL, 'Fast run-up with a launch angle near 45°', 'The correct term is: Fast run-up with a launch angle near 45°.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'If the launch speed doubles while the launch angle remains at 45°, approximately how many times greater will the range become?', NULL, NULL, NULL, NULL, 'Four times', 'The correct term is: Four times.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Which two variables determine the range and maximum height of a projectile?', NULL, NULL, NULL, NULL, 'Launch speed and launch angle', 'The correct term is: Launch speed and launch angle.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'At what point in its flight is a projectile''s total speed the slowest?', NULL, NULL, NULL, NULL, 'At the peak (top of the trajectory)', 'The correct term is: At the peak (top of the trajectory).', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'At what positions along the trajectory does a projectile have equal speed due to symmetry?', NULL, NULL, NULL, NULL, 'Any two points at the same height above the launch point', 'The correct term is: Any two points at the same height above the launch point.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Why do archers aim slightly above the target?', NULL, NULL, NULL, NULL, 'To compensate for gravity pulling the arrow downward', 'The correct term is: To compensate for gravity pulling the arrow downward.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Which pair of launch angles produces the same range but different maximum heights?', NULL, NULL, NULL, NULL, 'Any pair of complementary angles (e.g., 40° and 50°)', 'The correct term is: Any pair of complementary angles (e.g., 40° and 50°).', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Does horizontal motion affect the time required for vertical free fall?', NULL, NULL, NULL, NULL, 'No', 'The correct term is: No.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'As the launch angle increases from 0° to 45° to 90°, how do the range and maximum height change?', NULL, NULL, NULL, NULL, 'Range peaks at 45° then decreases; maximum height continues to increase', 'The correct term is: Range peaks at 45° then decreases; maximum height continues to increase.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Why does a launch angle of 45° produce the maximum range on level ground?', NULL, NULL, NULL, NULL, 'It balances horizontal speed and flight time', 'The correct term is: It balances horizontal speed and flight time.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'In an experiment with a fixed launch angle, how does increasing launch speed affect the range?', NULL, NULL, NULL, NULL, 'It increases approximately as the square of the launch speed', 'The correct term is: It increases approximately as the square of the launch speed.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'Which of the following is not an example of projectile motion?', NULL, NULL, NULL, NULL, 'Driving a car on a straight, flat road', 'The correct term is: Driving a car on a straight, flat road.', true),
('b0000000-0000-0000-0000-000000000301', 3, 'post_test', 'What is the shape of the ideal path followed by a projectile?', NULL, NULL, NULL, NULL, 'Parabola', 'The correct term is: Parabola.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The quantity defined as the product of an object''s mass and velocity.', NULL, NULL, NULL, NULL, 'Momentum', 'The correct term is: Momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The formula used to calculate momentum.', NULL, NULL, NULL, NULL, 'p = m × v', 'The correct term is: p = m × v.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Momentum describes how difficult it is to __________ a moving object.', NULL, NULL, NULL, NULL, 'Stop', 'The correct term is: Stop.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The two factors that determine an object''s momentum.', NULL, NULL, NULL, NULL, 'Mass and velocity', 'The correct term is: Mass and velocity.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'A collision in which no kinetic energy is lost and the objects bounce apart.', NULL, NULL, NULL, NULL, 'Elastic collision', 'The correct term is: Elastic collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'A collision in which the objects stick together or deform, causing kinetic energy to decrease.', NULL, NULL, NULL, NULL, 'Inelastic collision', 'The correct term is: Inelastic collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'In an isolated system, the total momentum before a collision is equal to the total momentum __________.', NULL, NULL, NULL, NULL, 'After the collision', 'The correct term is: After the collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The product of force and the time during which it acts.', NULL, NULL, NULL, NULL, 'Impulse', 'The correct term is: Impulse.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Seatbelts and airbags reduce the force during a collision by increasing the __________.', NULL, NULL, NULL, NULL, 'Stopping time (impact time)', 'The correct term is: Stopping time (impact time).', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'For objects with equal mass, what happens to momentum as speed increases?', NULL, NULL, NULL, NULL, 'Momentum increases', 'The correct term is: Momentum increases.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Billiard balls colliding and bouncing off with nearly the same speed are an example of what type of collision?', NULL, NULL, NULL, NULL, 'Nearly elastic collision', 'The correct term is: Nearly elastic collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Train cars coupling together after a collision demonstrate what type of collision?', NULL, NULL, NULL, NULL, 'Perfectly inelastic collision', 'The correct term is: Perfectly inelastic collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Between a jeepney and a motorcycle traveling at the same speed, which has the greater momentum?', NULL, NULL, NULL, NULL, 'Jeepney', 'The correct term is: Jeepney.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Catching an egg by moving your hand backward increases the __________, reducing the force on the egg.', NULL, NULL, NULL, NULL, 'Impact time (stopping time)', 'The correct term is: Impact time (stopping time).', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The recoil of a cannon after firing is explained by what physical principle?', NULL, NULL, NULL, NULL, 'Conservation of momentum', 'The correct term is: Conservation of momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Crumple zones in vehicles reduce the force of impact by increasing the __________ and __________.', NULL, NULL, NULL, NULL, 'Stopping distance and stopping time', 'The correct term is: Stopping distance and stopping time.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'In any collision involving an isolated system, what quantity is always conserved?', NULL, NULL, NULL, NULL, 'Total momentum', 'The correct term is: Total momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The form of energy that is conserved only in elastic collisions.', NULL, NULL, NULL, NULL, 'Kinetic energy', 'The correct term is: Kinetic energy.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'A 1 kg object moving at 5 m/s sticks to a 4 kg object at rest. What is their final speed?', NULL, NULL, NULL, NULL, '1 m/s', 'The correct term is: 1 m/s.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Why is falling onto a mattress less painful than falling onto concrete?', NULL, NULL, NULL, NULL, 'Longer stopping time results in a smaller force', 'The correct term is: Longer stopping time results in a smaller force.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Momentum is the product of what two quantities?', NULL, NULL, NULL, NULL, 'Mass and velocity', 'The correct term is: Mass and velocity.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Two balls moving at equal speeds toward each other and bouncing apart demonstrate what type of collision?', NULL, NULL, NULL, NULL, 'Elastic collision', 'The correct term is: Elastic collision.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'A boxer''s punch has large momentum mainly because of the __________ of the fist.', NULL, NULL, NULL, NULL, 'High velocity', 'The correct term is: High velocity.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'During a car crash, what effect does a longer impact time have on the force experienced?', NULL, NULL, NULL, NULL, 'It reduces the force', 'The correct term is: It reduces the force.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'The recoil of a fire hose when water is released demonstrates what law?', NULL, NULL, NULL, NULL, 'Conservation of momentum', 'The correct term is: Conservation of momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'According to the impulse-momentum theorem, the product of force and time equals the __________.', NULL, NULL, NULL, NULL, 'Change in momentum (Δp)', 'The correct term is: Change in momentum (Δp).', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'What is the main difference between elastic and inelastic collisions?', NULL, NULL, NULL, NULL, 'Kinetic energy is conserved in elastic collisions but not in inelastic collisions; momentum', 'The correct term is: Kinetic energy is conserved in elastic collisions but not in inelastic collisions; momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'When momentum is conserved during a collision, what quantity is exchanged between the objects?', NULL, NULL, NULL, NULL, 'Momentum', 'The correct term is: Momentum.', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Which object is harder to stop: a heavy, slow-moving object or a light, fast-moving object?', NULL, NULL, NULL, NULL, 'It depends on the product of mass and velocity (momentum)', 'The correct term is: It depends on the product of mass and velocity (momentum).', true),
('b0000000-0000-0000-0000-000000000302', 3, 'post_test', 'Safety devices such as airbags and seatbelts reduce injuries by increasing __________ to decrease force.', NULL, NULL, NULL, NULL, 'Stopping time', 'The correct term is: Stopping time.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy sources that are depleted after use and require millions of years to form.', NULL, NULL, NULL, NULL, 'Nonrenewable energy', 'The correct term is: Nonrenewable energy.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy sources that are naturally replenished within a relatively short period of time.', NULL, NULL, NULL, NULL, 'Renewable energy', 'The correct term is: Renewable energy.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'The primary source of electricity generation in the Philippines today.', NULL, NULL, NULL, NULL, 'Coal', 'The correct term is: Coal.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'The renewable energy resource in which the Philippines ranks second in the world.', NULL, NULL, NULL, NULL, 'Geothermal energy', 'The correct term is: Geothermal energy.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'The greenhouse gas mainly released when fossil fuels are burned.', NULL, NULL, NULL, NULL, 'Carbon dioxide (CO₂)', 'The correct term is: Carbon dioxide (CO₂).', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy produced from the movement or falling of water.', NULL, NULL, NULL, NULL, 'Hydropower (Hydroelectric power)', 'The correct term is: Hydropower (Hydroelectric power).', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy obtained directly from sunlight.', NULL, NULL, NULL, NULL, 'Solar energy', 'The correct term is: Solar energy.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy produced from organic materials such as agricultural waste, wood, and crops.', NULL, NULL, NULL, NULL, 'Biomass energy', 'The correct term is: Biomass energy.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'The major nonrenewable natural gas source in the Philippines.', NULL, NULL, NULL, NULL, 'Natural gas (Malampaya)', 'The correct term is: Natural gas (Malampaya).', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Why do renewable energy sources help reduce climate change?', NULL, NULL, NULL, NULL, 'They emit little to no CO₂ during operation', 'The correct term is: They emit little to no CO₂ during operation.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Identify the group composed only of nonrenewable energy sources.', NULL, NULL, NULL, NULL, 'Coal, oil, and natural gas', 'The correct term is: Coal, oil, and natural gas.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Identify the group composed only of renewable energy sources commonly used in the Philippines.', NULL, NULL, NULL, NULL, 'Geothermal, hydropower, solar, wind, and biomass', 'The correct term is: Geothermal, hydropower, solar, wind, and biomass.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'What is the major environmental effect of coal-fired power plants?', NULL, NULL, NULL, NULL, 'Air pollution and high carbon dioxide emissions', 'The correct term is: Air pollution and high carbon dioxide emissions.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'What is the primary disadvantage of constructing large hydroelectric dams?', NULL, NULL, NULL, NULL, 'Flooding and displacement of communities', 'The correct term is: Flooding and displacement of communities.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Why is geothermal energy highly suitable for the Philippines?', NULL, NULL, NULL, NULL, 'The Philippines is located along the Ring of Fire', 'The correct term is: The Philippines is located along the Ring of Fire.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'What economic benefit results from increasing the use of renewable energy sources?', NULL, NULL, NULL, NULL, 'Lower fuel imports and greater price stability', 'The correct term is: Lower fuel imports and greater price stability.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Solar and wind energy are classified as what type of energy sources because their output depends on weather conditions?', NULL, NULL, NULL, NULL, 'Intermittent energy sources', 'The correct term is: Intermittent energy sources.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Why is natural gas considered a transition fuel?', NULL, NULL, NULL, NULL, 'It is cleaner than coal but is still a finite fossil fuel', 'The correct term is: It is cleaner than coal but is still a finite fossil fuel.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Replacing coal-fired power plants helps reduce what health problem?', NULL, NULL, NULL, NULL, 'Respiratory illnesses caused by air pollution', 'The correct term is: Respiratory illnesses caused by air pollution.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'State one major advantage of wind energy.', NULL, NULL, NULL, NULL, 'Free fuel and low emissions', 'The correct term is: Free fuel and low emissions.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Compare the long-term cost of renewable energy with fossil fuels.', NULL, NULL, NULL, NULL, 'Renewable energy has higher installation costs but lower long-term operating costs', 'The correct term is: Renewable energy has higher installation costs but lower long-term operating costs.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'The Philippine goal of achieving 35% renewable energy by 2030 and 50% by 2040 primarily supports what two objectives?', NULL, NULL, NULL, NULL, 'Climate goals and energy security', 'The correct term is: Climate goals and energy security.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Geothermal and hydropower are classified as what type of renewable energy because they can provide continuous electricity?', NULL, NULL, NULL, NULL, 'Baseload renewable energy sources', 'The correct term is: Baseload renewable energy sources.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'What social issue is commonly associated with large energy development projects?', NULL, NULL, NULL, NULL, 'Local communities often bear the negative impacts of the projects', 'The correct term is: Local communities often bear the negative impacts of the projects.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Besides fuel costs, what other impacts should be included in the true cost of energy production?', NULL, NULL, NULL, NULL, 'Health, environmental, and climate impacts', 'The correct term is: Health, environmental, and climate impacts.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Coal ash and mining waste may release what harmful materials into the environment?', NULL, NULL, NULL, NULL, 'Toxic substances', 'The correct term is: Toxic substances.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Energy choices affect what four important aspects of society and electricity use?', NULL, NULL, NULL, NULL, 'Cost, reliability, emissions, and electricity bills', 'The correct term is: Cost, reliability, emissions, and electricity bills.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Give a reliable clean energy mix recommended for the Philippines.', NULL, NULL, NULL, NULL, 'Geothermal + Hydropower + Solar + Wind + Energy Storage', 'The correct term is: Geothermal + Hydropower + Solar + Wind + Energy Storage.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Why are renewable energy prices generally more stable than fossil fuel prices?', NULL, NULL, NULL, NULL, 'They have no fuel cost once the facilities are built', 'The correct term is: They have no fuel cost once the facilities are built.', true),
('b0000000-0000-0000-0000-000000000304', 3, 'post_test', 'Why is learning about renewable and nonrenewable energy important for students?', NULL, NULL, NULL, NULL, 'Because today''s energy choices will affect people''s lives and the environment in the', 'The correct term is: Because today''s energy choices will affect people''s lives and the environment in the.', true);
